var DateContorlObj=(function($){
	var curr = new Date().getFullYear(),
		startYear_range=100,
		endYear_range=100;
	var opt  = {
		'nomal':{
			theme: 'sense-ui',
			mode: 'scroller',
			lang: 'zh',
			display: 'modal',
			animate: 'none',
			dateFormat:'yy-mm-dd'

		},
		'date': {
		   preset: 'date',
		   // invalid: { daysOfWeek: [0, 6], daysOfMonth: ['5/1', '12/24', '12/25'] }
	       minDate: new Date((curr-startYear_range), 01, 01),
		   // maxDate: new Date(2116, 01, 01),
		   startYear: curr - startYear_range,
		   endYear:   curr + endYear_range
		},
		'datetime': {
			preset: 'datetime',
			 minDate: new Date((curr-startYear_range), 01, 01 ,  00, 00),
			//maxDate: new Date(2116, 01, 01, 00, 00),
			startYear: curr - startYear_range,
			endYear:   curr + endYear_range
		},
		'time': {
			preset: 'time',
			stepMinute: 1
		}
	};
	var isValidString=function(str_array){
		var result=false;
		if(Object.prototype.toString.call(str_array) !== '[object Array]'){
			throw new Error('setDateDefaultValue 参数必须是字符串数组！');
		}  
		
		result=str_array.every(function(item,key,array){
			return (typeof item==='string' && $.trim(item)!=='')
		});
		return result;
	};
	var testDateStr=function(dateStr,date_type){

		var	testReg=null,
			tipStr=date_type+'对应的日期类型的初始化字符串格式错误！例如 : ',
			result=false;
			
			switch(date_type){
				case 'date':
					testReg=/^\d{4,}-(?:0?\d|1[012])-(?:[012]?\d|3[01])$/;
					tipStr+='2016-01-01';
					break;
				case 'time':
					if(dateStr.length===8){ // 去掉末尾的秒
						dateStr=dateStr.substring(0,dateStr.length-3);
					}
					testReg=/^(?:[01]?\d|2[0-4]):(?:[0-5]?\d|60)$/;
					tipStr+='08:08';
					break;
				case 'datetime':
					if(dateStr.length===19){ // 去掉末尾的秒
						dateStr=dateStr.substring(0,dateStr.length-3);
					}
					testReg=/^\d{4,}-(?:0?\d|1[012])-(?:[012]?\d|3[01]) (?:[01]?\d|2[0-4]):(?:[0-5]?\d|60)$/;
					tipStr+='2016-01-01 08:08';
					break;
			}
			if(testReg.test(dateStr)){
				result=true;
			}else{
				throw new Error(tipStr);
			}
			return result;
	};
	var setDateDefaultValue=function(dateStr,date_type,input_id){
		if(!isValidString([date_type,input_id])){
				throw new Error('setDateDefaultValue 传参错误！');
		}
		var targetobj=$('#'+input_id);
		// 传入值为 Date对象时
		if(dateStr instanceof Date){
			var d=dateStr,
				dateobj={
					year:d.getFullYear(),
					month:d.getMonth()+1,
					day:d.getDate(),
					hour:d.getHours(),
					minute:d.getMinutes()
				},
				key='';
			for(key in dateobj){
				if(dateobj.hasOwnProperty(key)===true){
					if(dateobj[key].toString().length===1){
						dateobj[key]='0'+dateobj[key];
					}
				}
			}
			switch(date_type){
				case 'date':
					reslut=dateobj.year+'-'+dateobj.month+'-'+dateobj.day;
					break;
				case 'time':
					reslut=dateobj.hour+':'+dateobj.minute;
					break;
				case 'datetime':
					reslut=dateobj.year+'-'+dateobj.month+'-'+dateobj.day+' '+dateobj.hour+':'+dateobj.minute;
					break;
			}
			targetobj.val(reslut);
			return;

		// 传入值为字符串时
		}else if(isValidString([dateStr])){
			if(!(targetobj.length===1  && 
				 targetobj.attr('tag')===('date-control-'+date_type))){
				throw new Error('请为日期控件加上 tag="date-control-XXX"属性');
			}
			// 去掉末尾的秒
			if( (date_type==='time' && dateStr.length===8)      || 
				(date_type==='datetime' && dateStr.length===19) ){
				dateStr=dateStr.substring(0,dateStr.length-3);
			}
			if(testDateStr(dateStr,date_type)){
				targetobj.val(dateStr);
			}
		}
	};

	return {
		initDateControl:function(input_id,date_type,default_value,other_options){
			if(!isValidString([input_id,date_type])){
				throw new Error('initDateControl 传参错误！');
			}
			var targetobj=$('#'+input_id);
			if(!(targetobj.length===1  && 
				 targetobj.attr('tag')===('date-control-'+date_type))){
				 return false;
			}
			if(date_type!=='date' && 
			   date_type!=='time' && 
			   date_type!=='datetime'){
				 return false;
			}
			if(isValidString([default_value]) || default_value instanceof Date){
				setDateDefaultValue(default_value,date_type,input_id);
			}
			var optObj=other_options instanceof Object ? other_options : {};

			targetobj.scroller($.extend(opt['nomal'],opt[date_type],optObj));
			
		},
		setDateValue:function(dateStr,date_type,input_id){
			if(!isValidString([date_type,input_id])){
				throw new Error('setDateDefaultValue 传参错误！');
			}
			var reslut='',
			targetobj=$('#'+input_id);

			if(dateStr instanceof Date){
				targetobj.mobiscroll('setVal', dateStr, true, true);

			}else if(isValidString([dateStr])){
				if(!(targetobj.length===1  && 
				 	targetobj.attr('tag')===('date-control-'+date_type))){
					throw new Error('请为日期控件加上 tag="date-control-XXX"属性');
				}
				if(testDateStr(dateStr,date_type)){
					var dateAr   =null,
						date_part=null,
						time_part=null,
						year='',month='',day='',hour='',minute='';
					if(date_type==='date'){
						date_part=dateStr.split('-');
						year = parseInt(date_part[0]);
						month= parseInt(date_part[1]);
						day  = parseInt(date_part[2]);

						targetobj.mobiscroll('setVal', new Date(year,month,day), true, true);

					}else if(date_type==='datetime'){
						dateAr    = dateStr.split(' ');
						date_part = dateAr[0].split('-');
						year  = parseInt(date_part[0]);
						month = parseInt(date_part[1]);
						day   = parseInt(date_part[2]);

						time_part= dateAr[1].split(':');
						hour     = parseInt(time_part[0]);
						minute   = parseInt(time_part[1]);
						targetobj.mobiscroll('setVal', new Date(year,month,day,hour,minute), true, true);
					}
						
				}
			}
		},
		getDateValue:function(input_id){
			 if(!isValidString([input_id])){
				throw new Error('getDateValue 传参错误！');
			 }
			var targetobj=$('#'+input_id);
			if(targetobj.length===1  && 
				targetobj.val()!==''){
				return targetobj.val();
			}
		},
		open:function(input_id,related_id){
			var targetobj=$('#'+input_id);
				
			if(!(targetobj.length===1  && 
				 targetobj.attr('tag').indexOf('date-control-')>-1) ){
				 return false;
			}
			if(typeof related_id==='undefined'){
				targetobj.mobiscroll('show');
			}else if(typeof related_id==='string'){
				relatedobj=$('#'+related_id);
				relatedobj.unbind('click').on('click',function(){
					targetobj.mobiscroll('show');
				});
			}else if(related_id.constructor &&
				     related_id.constructor===jQuery){
				related_id.get(0).addEventListener('click',function(){
					targetobj.mobiscroll('show');
				},false);
			}
		},
		tranlateDateStr:function(input_id,to_id,date_type){
			var targetobj=$('#'+input_id);
			if(!(targetobj.length===1  && 
				 targetobj.attr('tag')===('date-control-'+date_type))){
				 return false;
			}
			var getReslut=function(){
				var valueText=$('#'+input_id).val(),
				dateStr=valueText.substring(0,valueText.indexOf(' ')),
				tiemStr=valueText.substring(valueText.indexOf(' '),valueText.length);
				dateAr=dateStr.split('-'),
				reslut='';
				if(date_type==='date'){
					reslut=dateAr[0]+'年'+dateAr[1]+'月'+dateAr[2]+'日';
				}else if(date_type==='datetime'){
					reslut=translate_dateStr=dateAr[0]+'年'+dateAr[1]+'月'+dateAr[2]+'日'+' '+tiemStr;
				}
				return reslut;
			};
			if(isValidString([$('#'+input_id).val()])){
				$('#'+to_id).html(getReslut());
			}

			$('#'+input_id).on('change',function(){
					$('#'+to_id).html(getReslut());
			});
		},
		addDateControlInfo:function(fild_Ar,fild_id,date_type,default_value){
			if(!$.isArray(DateContorlObj[fild_Ar])){
                DateContorlObj[fild_Ar]=[];
            }
            DateContorlObj[fild_Ar].push({
            	id:fild_id,
                date_type:date_type,
                default_value:default_value
            });
		},
		bingDateContrl:function(objStr){
			var d=DateContorlObj;
			if(typeof objStr ==='string'){
	            if($.isArray(d[objStr])){
	                $.each(d[objStr],function(i,item){
	                    if(item.id!==''){
	                        d.initDateControl(item.id,item.date_type,item.default_value);
	                        DateContorlObj.open(item.id,ld('#'+item.id).parent());
	                    }
	                });
	            }
		        d[objStr]=null;
			}
        }
	};

})(jQuery); 
